-- Migration 0034: audit entries must not be forgeable by a tenant session.
--
-- RLS keeps audit rows immutable to tenants, but urmail_record_audit accepted
-- ANY action string, so a member could append a row claiming a sensitive
-- compliance action happened (M6 review D4). The action is generated by the
-- API middleware as "<METHOD> <route>", so a conservative grammar is enforced
-- here: an action outside it is rejected instead of being recorded.
--
-- The function stays SECURITY DEFINER because it must append into audit_logs,
-- whose write grants are revoked from the app role; the scope check below is
-- what bounds it to the caller's own tenant.
CREATE OR REPLACE FUNCTION urmail_record_audit(p_tenant bigint,p_user bigint,p_ip inet,p_action text,p_target text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
 IF p_tenant IS DISTINCT FROM nullif(current_setting('urmail.tenant_id',true),'')::bigint OR p_user IS DISTINCT FROM nullif(current_setting('urmail.user_id',true),'')::bigint OR NOT EXISTS(SELECT 1 FROM user_tenant_roles WHERE tenant_id=p_tenant AND user_id=p_user) THEN RAISE EXCEPTION 'invalid audit scope' USING ERRCODE='42501'; END IF;
 IF p_action IS NULL OR p_action !~ '^[A-Za-z]{3,10} [A-Za-z0-9/{}:._~-]{0,120}$' THEN RAISE EXCEPTION 'invalid audit action' USING ERRCODE='22023'; END IF;
 IF length(p_action)>256 OR p_target IS NULL OR length(p_target)>2048 THEN RAISE EXCEPTION 'invalid audit metadata' USING ERRCODE='22023'; END IF;
 INSERT INTO audit_logs(tenant_id,actor_user_id,actor_ip,action,target_type,target_id) VALUES(p_tenant,p_user,p_ip,p_action,'http',p_target);
END $$;
ALTER FUNCTION urmail_record_audit(bigint,bigint,inet,text,text) OWNER TO urmail_platform;
REVOKE ALL ON FUNCTION urmail_record_audit(bigint,bigint,inet,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION urmail_record_audit(bigint,bigint,inet,text,text) TO urmail_app;
